UPDATE notification SET status = #{status},
       sent_at = CASE WHEN #{status} IN ('SENT', 'PARTIAL', 'FAILED', 'NO_TARGET') THEN now() ELSE sent_at END
WHERE id = #{id}

UPDATE admin_user SET email = #{email},
       mail_alerts = #{mailAlerts,typeHandler=org.apache.ibatis.type.ArrayTypeHandler}, updated_at = now()
WHERE id = #{adminId}

